private PendingDrop createPendingDrop() {
    if (this.dragOver < 0) {
        return new PendingDrop(this.dragKind, this.dragFrom, this.dragFrom, List.of(), null);
    }
    if (this.dragKind == DragKind.TEAM) {
        return new PendingDrop(this.dragKind, this.dragFrom, this.dragOver, List.of(), null);
    }
    ArrayList<UUID> members = new ArrayList<UUID>(ClientCompanionTeamState.members(this.target(), this.selectedTeam));
    if (this.dragFrom < 0 || this.dragFrom >= members.size() || this.dragOver < 0 || this.dragOver >= members.size()) {
        return new PendingDrop(this.dragKind, this.dragFrom, this.dragFrom, List.of(), null);
    }
    UUID moved = (UUID)members.remove(this.dragFrom);
    members.add(this.dragOver, moved);
    return new PendingDrop(this.dragKind, this.dragFrom, this.dragOver, List.copyOf(members), moved);
}

private void completePendingDrop() {
    PendingDrop drop = this.pendingDrop;
    CompanionTeamTarget currentTarget = this.target();
    int currentTeam = this.selectedTeam;
    this.clearDrag();
    if (drop == null || drop.from == drop.to) {
        return;
    }
    if (drop.kind == DragKind.TEAM) {
        int newSelectedTeam = FindMeAuiManageScreen.remapMovedIndex(this.selectedTeam, drop.from, drop.to);
        ClientCompanionTeamState.moveTeam(currentTarget, drop.from, drop.to);
        this.selectedTeam = newSelectedTeam;
        ClientCompanionTeamState.selectTeam(currentTarget, this.selectedTeam);
        ModNetwork.sendToServer(new CompanionTeamCommandPacket(CompanionTeamAction.REORDER, currentTarget, drop.from, drop.to, "", List.of()));
    } else if (drop.kind == DragKind.MEMBER && !drop.members.isEmpty()) {
        ClientCompanionTeamState.replaceMembers(currentTarget, currentTeam, drop.members);
        this.selectedUuid = drop.moved;
        ModNetwork.sendToServer(new CompanionTeamCommandPacket(CompanionTeamAction.SET, currentTarget, currentTeam, -1, "", drop.members));
    }
    this.refreshDocument();
}

