private void refreshSelectedTeamDom() {
    Document document = this.getLinkedDocument();
    if (document == null || this.view != View.TEAM) {
        this.refreshDocument();
        return;
    }
    Element workspace = document.querySelector(".fm-workspace");
    if (workspace == null) {
        this.refreshDocument();
        return;
    }
    for (Element row : document.querySelectorAll(".side-row[data-team-index]")) {
        int teamIndex = FindMeAuiManageScreen.parseInt(row.getAttribute("data-team-index"), -1);
        if (teamIndex == this.selectedTeam) {
            FindMeAuiManageScreen.addClass(row, "active");
            continue;
        }
        FindMeAuiManageScreen.removeClass(row, "active");
    }
    List<ClientCompanionTeamState.TeamEntry> teams = this.teams();
    List<Card> visibleCards = this.cards();
    workspace.setInnerHTML(this.workspaceHeader(teams, visibleCards.size()) + this.rosterMarkup(visibleCards));
    document.rebuildSelectorIndex();
    document.reapplyStylesFromCache();
    this.settleMainDomMutation();
    this.updateTeamScrollThumb();
}

