private void activateCard(UUID uuid) {
    Card card = this.findCard(uuid);
    if (card == null || !card.alive || this.view == View.DEAD || this.view == View.RECOVERY) {
        return;
    }
    if (this.view == View.WAREHOUSE) {
        return;
    }
    int memberIndex = ClientCompanionTeamState.members(this.target(), this.selectedTeam).indexOf(uuid);
    if (memberIndex < 0) {
        return;
    }
    if (this.category == Category.VEHICLE) {
        ClientMountRosterState.select(MountRosterSource.VEHICLE, card.uuid);
        ClientMountRosterTransactionState.send(card.active ? MountRosterAction.RECALL : MountRosterAction.ACTIVATE, MountRosterSource.VEHICLE, card.uuid, memberIndex, this.selectedTeam);
    } else {
        CompanionKind kind;
        CompanionKind companionKind = kind = this.category == Category.MOUNT ? CompanionKind.MOUNT : CompanionKind.COMPANION;
        if (kind == CompanionKind.MOUNT) {
            ClientMountRosterState.select(MountRosterSource.FIND_ME, card.uuid);
            ClientMountRosterTransactionState.send(card.active ? MountRosterAction.RECALL : MountRosterAction.ACTIVATE, MountRosterSource.FIND_ME, card.uuid, memberIndex, this.selectedTeam);
        } else if (card.active) {
            ModNetwork.sendToServer(new CompanionTeamCommandPacket(CompanionTeamAction.APPLY, this.target(), this.selectedTeam, -1, "", List.of()));
            ModNetwork.sendToServer(new CompanionCommandPacket(kind, CompanionAction.SELECT, memberIndex));
            ModNetwork.sendToServer(new CompanionCommandPacket(kind, CompanionAction.RETURN_HOME, -1));
        } else {
            ModNetwork.sendToServer(new CompanionTeamCommandPacket(CompanionTeamAction.APPLY, this.target(), this.selectedTeam, -1, "", List.of()));
            ModNetwork.sendToServer(new CompanionCommandPacket(kind, CompanionAction.SELECT_SUMMON, memberIndex));
        }
    }
