private void beginWarehouseSelection() {
    if (externalEditor != null) {
        this.warehouseSelection.clear();
        return;
    }
    this.warehouseSelection.begin(ClientCompanionTeamState.members(this.target(), this.selectedTeam), this.allCards().stream().filter(this::acceptedWarehouseCard).map(Card::uuid).toList());
}

private void replaceTeamMember(UUID uuid) {
    if (uuid == null || externalEditor != null) {
