    this.warehouseSelection.toggle(uuid);
    this.warehouseScrollTop = 0.0;
    this.search = "";
    this.selectedUuid = null;
    this.expandedUuid = null;
    this.contextOpen = false;
    this.pendingDanger = "";
    this.refreshDocument();
}

