    double rowHeight = 27.0;
    for (Element row : document.querySelectorAll("[data-team-index]")) {
        int index = FindMeAuiManageScreen.parseInt(row.getAttribute("data-team-index"), -1);
        if (index != teamIndex) continue;
        rowHeight = Math.max(1.0, Size.of((Element)row).height());
        break;
    }
    double viewport = Math.max(rowHeight, Box.of((Element)list).innerSize().height());
    double targetTop = Math.max(0.0, (double)teamIndex * rowHeight - Math.max(0.0, viewport - rowHeight));
    list.setScrollTop(targetTop);
    this.teamScrollTop = list.getTargetScrollTop();
    this.updateTeamScrollThumb();
}

